DROP TABLE IF EXISTS `pertanyaan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pertanyaan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `formulir_id` int NOT NULL,
  `tipe_pertanyaan` enum('text','paragraf','dropdown','checkbox','pilihanganda','upload','tandatangan') COLLATE utf8mb4_general_ci NOT NULL,
  `isi_pertanyaan` text COLLATE utf8mb4_general_ci NOT NULL,
  `pilihan` text COLLATE utf8mb4_general_ci,
  `wajib_diisi` tinyint(1) NOT NULL DEFAULT '1',
  `urutan` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `formulir_id` (`formulir_id`),
  CONSTRAINT `pertanyaan_ibfk_1` FOREIGN KEY (`formulir_id`) REFERENCES `formulir` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1442 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

